<?php
require_once __DIR__ . '/../../../backend/includes/auth.php';
require_role(['admin','super_admin','inventory_manager']);
$isAdmin=in_array(current_role(),['admin','super_admin'],true);$message='';$error='';
function next_po_number(PDO $pdo):string{for($i=0;$i<20;$i++){$n='PO-'.date('Ymd').'-'.str_pad((string)random_int(1,9999),4,'0',STR_PAD_LEFT);$s=$pdo->prepare('SELECT 1 FROM purchase_orders WHERE po_number=?');$s->execute([$n]);if(!$s->fetchColumn())return $n;}throw new RuntimeException('Unable to generate a purchase-order number.');}
function refresh_po_status(PDO $pdo,int $poId):void{$s=$pdo->prepare('SELECT COALESCE(SUM(ordered_qty),0) o,COALESCE(SUM(received_qty),0) r FROM purchase_order_items WHERE purchase_order_id=?');$s->execute([$poId]);$x=$s->fetch(PDO::FETCH_ASSOC);if(!$x)return;$status=(int)$x['r']<=0?null:((int)$x['r']>=(int)$x['o']?'fully_received':'partially_received');if($status)$pdo->prepare("UPDATE purchase_orders SET status=? WHERE purchase_order_id=? AND status NOT IN ('cancelled')")->execute([$status,$poId]);}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$action=$_POST['action']??'';try{
if($action==='create'){$supplierId=(int)($_POST['supplier_id']??0);$ids=array_values(array_filter(array_map('intval',$_POST['request_ids']??[])));if(!$supplierId||!$ids)throw new RuntimeException('Select a supplier and at least one approved request.');$pdo->beginTransaction();$po=next_po_number($pdo);$stmt=$pdo->prepare("INSERT INTO purchase_orders(po_number,supplier_id,status,expected_delivery_date,notes,created_by) VALUES(?,?,'draft',?,?,?)");$stmt->execute([$po,$supplierId,($_POST['expected_delivery_date']??'')?:null,trim((string)($_POST['notes']??''))?:null,(int)$_SESSION['user_id']]);$poId=(int)$pdo->lastInsertId();$ph=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT rr.request_id,rr.product_id,rr.request_qty,p.cost_price FROM replenishment_requests rr JOIN products p ON p.product_id=rr.product_id WHERE rr.request_id IN ($ph) AND rr.status='approved' AND NOT EXISTS (SELECT 1 FROM purchase_order_items poi2 JOIN purchase_orders po2 ON po2.purchase_order_id=poi2.purchase_order_id WHERE poi2.replenishment_request_id=rr.request_id AND po2.status<>'cancelled') FOR UPDATE");$q->execute($ids);$rows=$q->fetchAll(PDO::FETCH_ASSOC);if(count($rows)!==count($ids))throw new RuntimeException('One or more requests are no longer available.');$ins=$pdo->prepare('INSERT INTO purchase_order_items(purchase_order_id,replenishment_request_id,product_id,ordered_qty,unit_cost) VALUES(?,?,?,?,?)');foreach($rows as $r)$ins->execute([$poId,$r['request_id'],$r['product_id'],$r['request_qty'],$r['cost_price']]);$pdo->commit();log_activity($pdo,(int)$_SESSION['user_id'],'Created purchase order','Purchase Orders',$poId,null,['po_number'=>$po]);$message="Purchase order {$po} created as draft.";}
elseif(in_array($action,['approve','sent','cancel'],true)){$poId=(int)($_POST['purchase_order_id']??0);if(!$poId)throw new RuntimeException('Invalid purchase order.');if($action==='approve'){if(!$isAdmin)throw new RuntimeException('Only an administrator can approve purchase orders.');$stmt=$pdo->prepare("UPDATE purchase_orders SET status='approved',approved_by=?,approved_at=NOW() WHERE purchase_order_id=? AND status='draft' AND created_by<>?");$stmt->execute([(int)$_SESSION['user_id'],$poId,(int)$_SESSION['user_id']]);}elseif($action==='sent'){$stmt=$pdo->prepare("UPDATE purchase_orders SET status='sent',sent_at=NOW() WHERE purchase_order_id=? AND status='approved'");$stmt->execute([$poId]);}else{$stmt=$pdo->prepare("UPDATE purchase_orders SET status='cancelled',cancelled_at=NOW() WHERE purchase_order_id=? AND status IN ('draft','approved','sent')");$stmt->execute([$poId]);}if($stmt->rowCount()===0)throw new RuntimeException('Purchase order status could not be changed.');log_activity($pdo,(int)$_SESSION['user_id'],ucfirst($action).' purchase order','Purchase Orders',$poId);$message='Purchase order updated.';}
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$available=$pdo->query("SELECT rr.request_id,rr.request_qty,rr.request_date,p.product_name,p.sku,p.preferred_supplier FROM replenishment_requests rr JOIN products p ON p.product_id=rr.product_id WHERE rr.status='approved' AND NOT EXISTS (SELECT 1 FROM purchase_order_items poi2 JOIN purchase_orders po2 ON po2.purchase_order_id=poi2.purchase_order_id WHERE poi2.replenishment_request_id=rr.request_id AND po2.status<>'cancelled') ORDER BY rr.request_date")->fetchAll(PDO::FETCH_ASSOC);
$suppliers=$pdo->query("SELECT supplier_id,supplier_name FROM suppliers WHERE status='active' ORDER BY supplier_name")->fetchAll(PDO::FETCH_ASSOC);
$orders=$pdo->query("SELECT po.*,s.supplier_name,u.full_name created_by_name,au.full_name approved_by_name,COUNT(poi.purchase_order_item_id) item_lines,COALESCE(SUM(poi.ordered_qty),0) ordered_qty,COALESCE(SUM(poi.received_qty),0) received_qty,COALESCE(SUM(poi.ordered_qty*poi.unit_cost),0) total_value FROM purchase_orders po LEFT JOIN suppliers s ON s.supplier_id=po.supplier_id JOIN users u ON u.user_id=po.created_by LEFT JOIN users au ON au.user_id=po.approved_by LEFT JOIN purchase_order_items poi ON poi.purchase_order_id=po.purchase_order_id GROUP BY po.purchase_order_id ORDER BY po.created_at DESC")->fetchAll(PDO::FETCH_ASSOC);
$items=$pdo->query("SELECT poi.*,po.po_number,p.product_name,p.sku FROM purchase_order_items poi JOIN purchase_orders po ON po.purchase_order_id=poi.purchase_order_id JOIN products p ON p.product_id=poi.product_id ORDER BY po.created_at DESC,p.product_name")->fetchAll(PDO::FETCH_ASSOC);$itemsBy=[];foreach($items as $i)$itemsBy[(int)$i['purchase_order_id']][]=$i;
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Purchase Orders</title><link rel="stylesheet" href="<?=htmlspecialchars(app_url('assets/css/style.css'))?>"><style>.po-card{margin-bottom:1rem}.po-head{display:flex;justify-content:space-between;gap:1rem;align-items:start}.request-list{max-height:330px;overflow:auto;border:1px solid #ddd;padding:.5rem}.request-option{display:block;padding:.6rem;border-bottom:1px solid #eee}</style></head><body><div class="app-shell"><?php include __DIR__.'/../sidebar.php';?><main class="main-content"><div class="topbar"><div><h1>Purchase Orders</h1><p class="page-subtitle">Convert approved replenishment requests into trackable supplier orders.</p></div><a class="btn" href="<?=htmlspecialchars(app_url('modules/inventory_management/suppliers.php'))?>">Suppliers</a></div><?php if($message):?><div class="message success"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="message error"><?=htmlspecialchars($error)?></div><?php endif;?>
<section class="dashboard-section"><h3>Create from approved requests</h3><?php if(!$available):?><p>No approved requests are waiting for a purchase order.</p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(generate_csrf_token())?>"><input type="hidden" name="action" value="create"><label>Supplier</label><select name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['supplier_id']?>"><?=htmlspecialchars($s['supplier_name'])?></option><?php endforeach;?></select><label>Expected delivery date</label><input type="date" name="expected_delivery_date"><label>Approved requests</label><div class="request-list"><?php foreach($available as $r):?><label class="request-option"><input type="checkbox" name="request_ids[]" value="<?=$r['request_id']?>"> <strong><?=htmlspecialchars($r['product_name'])?></strong> — <?=(int)$r['request_qty']?> units <small>(<?=htmlspecialchars($r['preferred_supplier']?:'No preferred supplier')?>)</small></label><?php endforeach;?></div><label>Notes</label><textarea name="notes"></textarea><button class="btn">Create draft PO</button></form><?php endif;?></section>
<?php foreach($orders as $po):?><section class="dashboard-section po-card"><div class="po-head"><div><h3><?=htmlspecialchars($po['po_number'])?></h3><p><?=htmlspecialchars($po['supplier_name']??'Supplier not assigned')?> · <?=htmlspecialchars(ucwords(str_replace('_',' ',$po['status'])))?> · Expected <?=htmlspecialchars($po['expected_delivery_date']??'-')?></p></div><div><strong>₱<?=number_format((float)$po['total_value'],2)?></strong><br><small><?=(int)$po['received_qty']?> / <?=(int)$po['ordered_qty']?> units received</small></div></div><div class="table-wrap"><table><tr><th>Product</th><th>Ordered</th><th>Received</th><th>Unit cost</th></tr><?php foreach($itemsBy[(int)$po['purchase_order_id']]??[] as $i):?><tr><td><?=htmlspecialchars($i['product_name'])?><br><small><?=htmlspecialchars($i['sku'])?></small></td><td><?=(int)$i['ordered_qty']?></td><td><?=(int)$i['received_qty']?></td><td>₱<?=number_format((float)$i['unit_cost'],2)?></td></tr><?php endforeach;?></table></div><div style="display:flex;gap:.5rem;flex-wrap:wrap"><?php if($po['status']==='draft'&&$isAdmin&&(int)$po['created_by']!==(int)$_SESSION['user_id']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(generate_csrf_token())?>"><input type="hidden" name="action" value="approve"><input type="hidden" name="purchase_order_id" value="<?=$po['purchase_order_id']?>"><button class="btn">Approve</button></form><?php elseif($po['status']==='draft'&&$isAdmin):?><small>Approval must be completed by a different administrator.</small><?php endif;?><?php if($po['status']==='approved'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(generate_csrf_token())?>"><input type="hidden" name="action" value="sent"><input type="hidden" name="purchase_order_id" value="<?=$po['purchase_order_id']?>"><button class="btn">Mark sent</button></form><?php endif;?><?php if(in_array($po['status'],['draft','approved','sent'],true)):?><form method="post" data-confirm="Cancel this purchase order? This action will be recorded." data-confirm-title="Cancel purchase order" data-confirm-button="Cancel order" data-confirm-danger="1"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(generate_csrf_token())?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="purchase_order_id" value="<?=$po['purchase_order_id']?>"><button class="btn btn-danger">Cancel</button></form><?php endif;?><button class="btn btn-secondary" onclick="window.print()">Print</button></div></section><?php endforeach;?>
</main></div></body></html>
